DO $$
DECLARE
  rec RECORD;
  cur_status VARCHAR(20);
  cur_reviewer INTEGER;
BEGIN
  FOR rec IN SELECT * FROM review_events ORDER BY event_id LOOP
    SELECT status, reviewer_id INTO cur_status, cur_reviewer FROM claim_lines WHERE line_id = rec.line_id;
    IF rec.event_type = 1 AND cur_status = 'pending' THEN
      UPDATE claim_lines SET status = 'under_review', reviewer_id = rec.clinician_id WHERE line_id = rec.line_id;
    ELSIF rec.event_type = 2 AND cur_status = 'under_review' AND cur_reviewer = rec.clinician_id THEN
      UPDATE claim_lines SET status = 'approved', approved_code = rec.diag_code WHERE line_id = rec.line_id;
    ELSIF rec.event_type = 3 AND cur_status = 'under_review' AND cur_reviewer = rec.clinician_id THEN
      UPDATE claim_lines SET status = 'denied', denial_reason = rec.reason_text WHERE line_id = rec.line_id;
    ELSIF rec.event_type = 4 AND cur_status = 'denied' THEN
      UPDATE claim_lines SET status = 'pending', reviewer_id = NULL, denial_reason = NULL WHERE line_id = rec.line_id;
    END IF;
  END LOOP;
END $$;
SELECT * FROM claim_lines ORDER BY line_id;
